function withLock<T>(fn: () => T): T {
    while (Atomics.compareExchange(lock, 0, 0, 1) !== 0) Atomics.wait(lock, 0, 1);
    try { return fn(); }
    finally { Atomics.store(lock, 0, 0); Atomics.notify(lock, 0, 1); }
}
